class Account {
    private int balance;
    public Account(int start) { balance = start; }
    public void deposit(int amt) {
        if (amt > 0) {
            balance += amt;
        }
    }
    public boolean withdraw(int amt) {
        if (amt > 0 && amt <= balance) {
            balance -= amt;
            return true;
        }
        return false;
    }
    public int getBalance() { return balance; }
}

public class Client {
    public static void main(String[] args) {
        Account acct = new Account(21);
        acct.deposit(13);
        boolean r1 = acct.withdraw(38);
        acct.deposit(-24);
        boolean r2 = acct.withdraw(120);
        System.out.println(r1 + " " + r2 + " " + acct.getBalance());
    }
}
```

